class Solution:
    def beautifulSubstrings(self, s, k):
        m = 1
        kk = k
        p = 2
        while p * p <= kk:
            if kk % p == 0:
                e = 0
                while kk % p == 0:
                    kk //= p
                    e += 1
                for _ in range((e + 1) // 2):
                    m *= p
            p += 1
        if kk > 1:
            m *= kk
        L = 2 * m
        cnt = {(0, 0): 1}
        bal = ans = 0
        vowels = set('aeiou')
        for i, ch in enumerate(s):
            bal += 1 if ch in vowels else -1
            key = (bal, (i + 1) % L)
            ans += cnt.get(key, 0)
            cnt[key] = cnt.get(key, 0) + 1
        return ans

