class Solution {
public:
    long long beautifulSubstrings(string s, int k) {
        long long m = 1;
        int kk = k;
        for (long long p = 2; p * p <= kk; p++) {
            if (kk % p == 0) {
                int e = 0;
                while (kk % p == 0) { kk /= p; e++; }
                for (int t = 0; t < (e + 1) / 2; t++) m *= p;
            }
        }
        if (kk > 1) m *= kk;
        long long L = 2 * m;
        map<pair<long long,long long>, long long> cnt;
        cnt[{0, 0}] = 1;
        long long bal = 0, ans = 0;
        auto isVowel = [](char c) {
            return c=='a'||c=='e'||c=='i'||c=='o'||c=='u';
        };
        for (int i = 0; i < (int)s.size(); i++) {
            bal += isVowel(s[i]) ? 1 : -1;
            auto key = make_pair(bal, (i + 1) % L);
            auto it = cnt.find(key);
            if (it != cnt.end()) { ans += it->second; it->second++; }
            else cnt[key] = 1;
        }
        return ans;
    }
};

