class Solution {
    public long beautifulSubstrings(String s, int k) {
        long m = 1;
        int kk = k;
        for (long p = 2; p * p <= kk; p++) {
            if (kk % p == 0) {
                int e = 0;
                while (kk % p == 0) { kk /= p; e++; }
                for (int t = 0; t < (e + 1) / 2; t++) m *= p;
            }
        }
        if (kk > 1) m *= kk;
        long L = 2 * m;
        Map<Long, Long> cnt = new HashMap<>();
        cnt.put(0L, 1L);
        long bal = 0, ans = 0;
        for (int i = 0; i < s.length(); i++) {
            bal += "aeiou".indexOf(s.charAt(i)) >= 0 ? 1 : -1;
            long key = bal * 100000L + ((i + 1) % L);
            ans += cnt.getOrDefault(key, 0L);
            cnt.merge(key, 1L, Long::sum);
        }
        return ans;
    }
}

c.javascript:
var beautifulSubstrings = function(s, k) {
    let m = 1, kk = k;
    for (let p = 2; p * p <= kk; p++) {
        if (kk % p === 0) {
            let e = 0;
            while (kk % p === 0) { kk /= p; e++; }
            for (let t = 0; t < ((e + 1) >> 1); t++) m *= p;
        }
    }
    if (kk > 1) m *= kk;
    const L = 2 * m;
    const cnt = new Map([["0,0", 1]]);
    let bal = 0, ans = 0;
    const vowels = new Set(["a","e","i","o","u"]);
    for (let i = 0; i < s.length; i++) {
        bal += vowels.has(s[i]) ? 1 : -1;
        const key = bal + "," + ((i + 1) % L);
        const c = cnt.get(key) || 0;
        ans += c;
        cnt.set(key, c + 1);
    }
    return ans;
};
